arguments.command:
python3 -c "
import codecs
print('CP1252 encoding table:')
for i in range(0x80, 0x100):
    c = chr(i)
    try:
        encoded = codecs.encode(c, 'cp1252')
        if encoded != bytes([i]):
            print(f'  {hex(i)}: chr={repr(c)}, encoded={repr(encoded)}')
    except Exception as e:
        print(f'  {hex(i)}: chr={repr(c)}, error={e}')
"

